//! `image_dimensions` is a hand-rolled container-header parser, and a
//! hand-rolled parser is only trustworthy when it is forced to agree with the
//! real one. These tests pin the contract:
//!
//! 1. **Differential agreement** — for valid files in every supported format,
//!    this crate's header read and `image::load_from_memory` must report the
//!    same dimensions. Format fixtures are generated by the `image` crate
//!    itself, so the reference side is the production decoder, not a
//!    hand-written table.
//! 2. **Totality** — truncation, mutation and garbage produce `Ok` or `Err`,
//!    never a panic.

use hikari_core::{image_dimensions, Error};
use image::codecs::gif::GifEncoder;
use image::codecs::jpeg::JpegEncoder;
use image::codecs::png::PngEncoder;
use image::codecs::webp::WebPEncoder;
use image::{ExtendedColorType, ImageEncoder, ImageFormat, ImageResult};

/// A deterministic, dependency-free xorshift; only drives mutation selection,
/// so reproducibility matters and distribution quality does not.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
}

fn encode(format: ImageFormat, w: u32, h: u32) -> Vec<u8> {
    let mut out = Vec::new();
    match format {
        ImageFormat::Png => {
            PngEncoder::new(&mut out)
                .write_image(&rgb(w, h), w, h, ExtendedColorType::Rgb8)
                .unwrap_or_else(|e| panic!("png: {e}"));
        }
        ImageFormat::Jpeg => {
            JpegEncoder::new(&mut out)
                .encode(&rgb(w, h), w, h, ExtendedColorType::Rgb8)
                .unwrap_or_else(|e| panic!("jpeg: {e}"));
        }
        ImageFormat::Gif => {
            GifEncoder::new(&mut out)
                .encode_frame(image::Frame::new(rgba(w, h)))
                .unwrap_or_else(|e| panic!("gif: {e}"));
        }
        ImageFormat::WebP => {
            WebPEncoder::new_lossless(&mut out)
                .write_image(&rgb(w, h), w, h, ExtendedColorType::Rgb8)
                .unwrap_or_else(|e| panic!("webp: {e}"));
        }
        _ => unreachable!(),
    }
    out
}

fn rgb(w: u32, h: u32) -> Vec<u8> {
    let mut out = Vec::with_capacity((w * h * 3) as usize);
    for y in 0..h {
        for x in 0..w {
            out.push(((x * 37) % 255) as u8);
            out.push(((y * 61) % 255) as u8);
            out.push((((x ^ y) * 23) % 255) as u8);
        }
    }
    out
}

fn rgba(w: u32, h: u32) -> image::RgbaImage {
    image::ImageBuffer::from_fn(w, h, |x, y| {
        [
            ((x * 37) % 255) as u8,
            ((y * 61) % 255) as u8,
            (((x ^ y) * 23) % 255) as u8,
            255,
        ]
        .into()
    })
}

fn decoded(bytes: &[u8]) -> ImageResult<(u32, u32)> {
    image::load_from_memory(bytes).map(|img| (img.width(), img.height()))
}

/// Same answer as the decoder, all four formats, several sizes.
#[test]
fn header_agrees_with_the_real_decoder_on_valid_files() {
    for &(w, h) in &[(1u32, 1u32), (13, 17), (255, 255), (1200, 630)] {
        for format in [
            ImageFormat::Png,
            ImageFormat::Jpeg,
            ImageFormat::Gif,
            ImageFormat::WebP,
        ] {
            let bytes = encode(format, w, h);
            let by_header = image_dimensions(&bytes)
                .unwrap_or_else(|e| panic!("{format:?} {w}x{h}: header parse failed: {e}"));
            let by_decoder = decoded(&bytes)
                .unwrap_or_else(|e| panic!("{format:?} {w}x{h}: reference decode failed: {e}"));
            assert_eq!(by_header, by_decoder, "{format:?} {w}x{h}");
        }
    }
}

/// Truncated input rustles. Note the asymmetry that is the point of the
/// header read: a cut inside the header errors; a cut after the header still
/// succeeds, because layout only needs the size, and paint will do the
/// full-decode validation later — exactly as the old path did.
#[test]
fn truncation_never_panics() {
    for format in [
        ImageFormat::Png,
        ImageFormat::Jpeg,
        ImageFormat::Gif,
        ImageFormat::WebP,
    ] {
        let bytes = encode(format, 37, 53);
        for cut in 0..=bytes.len().min(128) {
            let _ = image_dimensions(&bytes[..cut]);
        }
    }
}

/// Mutated input: no panic, whatever the answer. This is what the fuzz corpus
/// covers in broad strokes; running it under plain `cargo test` keeps the
/// guarantee cheap between fuzz runs.
#[test]
fn mutated_input_never_panics() {
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    for format in [
        ImageFormat::Png,
        ImageFormat::Jpeg,
        ImageFormat::Gif,
        ImageFormat::WebP,
    ] {
        let bytes = encode(format, 37, 53);
        for _ in 0..100 {
            let mut mutated = bytes.clone();
            let pos = usize::try_from(rng.next() % bytes.len() as u64).unwrap();
            match rng.next() % 4 {
                // ( % 4 keeps the arms exhaustive; the doc comment above
                // explains why a deterministic RNG is fine here )
                0 => mutated[pos] = (rng.next() & 0xFF) as u8,
                1 => mutated[pos] ^= (rng.next() & 0xFF) as u8,
                2 => {
                    let cut = pos.max(1);
                    mutated.truncate(cut);
                }
                // Make a truncated file pretend to start with a JPEG SOI,
                // so the segment scanner is exercised from non-JPEG input.
                3 => {
                    mutated.truncate(pos.max(16));
                    mutated[0] = 0xFF;
                    mutated[1] = 0xD8;
                }
                _ => {}
            }
            let result = image_dimensions(&mutated);
            match result {
                Ok((w, h)) if w > 0 && h <= 100_000 && w <= 100_000 => {}
                Err(Error::Asset(_)) => {}
                other => panic!("unexpected result class {other:?}"),
            }
        }
    }
}

/// Synthetic headers for the two WebP shapes the `image` crate cannot write:
/// a lossy VP8 keyframe and a VP8X extended file. Header-only parsing is the
/// point, so the fixtures assert on the first 30 bytes only.
#[test]
fn webp_vp8_lossy_and_vp8x_shapes() {
    let (w, h) = (819u16, 313u16);
    let dims = (u32::from(w), u32::from(h));

    let mut vp8 = Vec::new();
    vp8.extend_from_slice(b"RIFF");
    vp8.extend_from_slice(&30u32.to_le_bytes());
    vp8.extend_from_slice(b"WEBP");
    vp8.extend_from_slice(b"VP8 ");
    vp8.extend_from_slice(&10u32.to_le_bytes());
    vp8.extend_from_slice(&[0x00, 0x00, 0x00]);
    vp8.extend_from_slice(&[0x9D, 0x01, 0x2A]);
    vp8.extend_from_slice(&(w & 0x3FFF).to_le_bytes());
    vp8.extend_from_slice(&(h & 0x3FFF).to_le_bytes());
    assert_eq!(image_dimensions(&vp8).unwrap_or((0, 0)), dims);

    // VP8X canvas size, stored as value-one, 24 bits each.
    let vp8x = |w: u32, h: u32| -> Vec<u8> {
        let mut b = Vec::new();
        b.extend_from_slice(b"RIFF");
        b.extend_from_slice(&(4u32 + 18).to_le_bytes());
        b.extend_from_slice(b"WEBP");
        b.extend_from_slice(b"VP8X");
        b.extend_from_slice(&18u32.to_le_bytes());
        b.extend_from_slice(&[0, 0, 0, 0]);
        for value in [w - 1, h - 1] {
            b.push((value & 0xFF) as u8);
            b.push(((value >> 8) & 0xFF) as u8);
            b.push(((value >> 16) & 0xFF) as u8);
        }
        b
    };
    assert_eq!(
        image_dimensions(&vp8x(1200, 630)).unwrap_or((0, 0)),
        (1200, 630)
    );
    assert_eq!(image_dimensions(&vp8x(1, 1)).unwrap_or((0, 0)), (1, 1));
}

/// Non-image bytes: errors, every time.
#[test]
fn unrecognised_input_errors() {
    assert!(image_dimensions(&[]).is_err(), "empty must error");
    assert!(image_dimensions(b"\xFF").is_err(), "one byte must error");
    assert!(
        image_dimensions(b"RIFFBlahWEBP").is_err(),
        "short RIFF must error"
    );
    assert!(image_dimensions(b"not a png at all").is_err());
}

/// A PNG whose IHDR is not the first chunk: malformed, not a silent fallback.
#[test]
fn png_with_wrong_first_chunk_errors() {
    let mut b = vec![0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A];
    b.extend_from_slice(&[0, 0, 0, 1]);
    b.extend_from_slice(b"IDAT");
    b.extend_from_slice(&[0, 0, 3, 0, 0, 0, 1, 1, 0]);
    assert!(image_dimensions(&b).is_err());
}
